<div class="crpcrm-request-filters"><form method="get"><input type="hidden" name="page" value="crpcrm-staff"><input type="hidden" name="staff_tab" value="daily_reports"><div class="crpcrm-filter-grid"><label>تاریخ<?php echo CRPCRM_Helpers::jalali_date_input( 'report_date', $filters['report_date'] ?? '' ); ?></label><?php if($can_manage): ?><label>کارمند<select name="user_id"><option value="">همه</option><?php foreach($staff_users as $u): ?><option value="<?php echo esc_attr($u->ID); ?>" <?php selected($filters['user_id'] ?? '',$u->ID); ?>><?php echo esc_html($u->display_name); ?></option><?php endforeach; ?></select></label><?php endif; ?><label>وضعیت<select name="status"><option value="">همه</option><?php foreach($report_statuses as $k=>$v): ?><option value="<?php echo esc_attr($k); ?>" <?php selected($filters['status'] ?? '',$k); ?>><?php echo esc_html($v); ?></option><?php endforeach; ?></select></label><label>نیازمند توجه<select name="needs_manager_attention"><option value="">همه</option><option value="1" <?php selected($filters['needs_manager_attention'] ?? '','1'); ?>>بله</option><option value="0" <?php selected($filters['needs_manager_attention'] ?? '','0'); ?>>خیر</option></select></label></div><?php submit_button('اعمال فیلتر','secondary','',false); ?></form></div>
